+static int mysql_test_dropped_query(MYSQL *mysql_conn, const char *query)
+{
+  struct pollfd reply;
+  char discarded[512];
+
+  reply.fd = mysql_get_socket(mysql_conn);
+  reply.events = POLLIN;
+  if (!test_drop_after_sending)
