+static int saves_player_rows(struct transactions_world *w)
+{
+  return transactions_value(w->observer,
+                            "SELECT COUNT(*) FROM player_save_objs WHERE name = '" SAVES_OWNER
+                            "' LOCK IN SHARE MODE");
+}
